window.printPackagingPurchaseReport=()=>{let f=$('#rFrom')?.value||'',to=$('#rTo')?.value||today(),rows=db.packagingTx.filter(x=>x.mode==='IN'&&(!f||x.date>=f)&&(!to||x.date<=to)).sort((a,b)=>a.date.localeCompare(b.date)),qty=rows.reduce((s,x)=>s+Number(x.qty||0),0),val=rows.reduce((s,x)=>s+Number(x.qty||0)*Number(x.cost||0),0);let by={};rows.forEach(x=>{let item=db.packaging.find(p=>p.id===x.itemId),k=x.itemId||x.itemName;if(!by[k])by[k]={name:x.itemName,type:packTypeLabel(item?.type),qty:0,value:0};by[k].qty+=Number(x.qty||0);by[k].value+=Number(x.qty||0)*Number(x.cost||0)});printWindow('Pembelian Packaging',`<h2>LAPORAN PEMBELIAN PACKAGING</h2><div class="muted">Periode: ${f?dateID(f):'Awal data'} s.d. ${to?dateID(to):'Akhir data'}</div><div class="summary"><div class="box"><b>${rows.length}</b>Transaksi</div><div class="box"><b>${fmt(qty)}</b>Total Qty</div><div class="box"><b>${money(val)}</b>Total Pembelian</div></div><h2>Ringkasan per Packaging</h2><table class="compact"><thead><tr><th>Packaging</th><th>Jenis</th><th class="num">Qty</th><th class="num">Nilai</th></tr></thead><tbody>${Object.values(by).map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.type)}</td><td class="num">${fmt(x.qty)}</td><td class="num">${money(x.value)}</td></tr>`).join('')||'<tr><td colspan="4">Belum ada data</td></tr>'}</tbody></table><h2>Detail Pembelian</h2><table class="compact"><thead><tr><th>Tanggal</th><th>Packaging</th><th class="num">Qty</th><th class="num">Harga/Unit</th><th class="num">Jumlah</th><th>Catatan</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${dateID(x.date)}</td><td>${esc(x.itemName)}</td><td class="num">${fmt(x.qty)}</td><td class="num">${money(x.cost)}</td><td class="num">${money(Number(x.qty||0)*Number(x.cost||0))}</td><td>${esc(x.note||'-')}</td></tr>`).join('')||'<tr><td colspan="6">Belum ada data</td></tr>'}</tbody></table>`,'report')}
window.printProductionReport=()=>{let f=$('#rFrom')?.value||'',to=$('#rTo')?.value||today(),rows=db.productions.filter(x=>(!f||x.date>=f)&&(!to||x.date<=to)).sort((a,b)=>a.date.localeCompare(b.date)),good=rows.reduce((s,x)=>s+Number(x.qty||0),0),reject=rows.reduce((s,x)=>s+Number(x.reject||0),0),by={};rows.forEach(x=>{let k=x.productId||x.productName;if(!by[k])by[k]={name:x.productName,good:0,reject:0};by[k].good+=Number(x.qty||0);by[k].reject+=Number(x.reject||0)});printWindow('Hasil Produksi',`<h2>LAPORAN HASIL PRODUKSI</h2><div class="muted">Periode: ${f?dateID(f):'Awal data'} s.d. ${to?dateID(to):'Akhir data'}</div><div class="summary"><div class="box"><b>${rows.length}</b>Transaksi</div><div class="box"><b>${fmt(good)}</b>Good</div><div class="box"><b>${fmt(reject)}</b>Reject</div></div><h2>Ringkasan per Produk</h2><table class="compact"><thead><tr><th>Produk</th><th class="num">Good</th><th class="num">Reject</th><th class="num">Total Proses</th></tr></thead><tbody>${Object.values(by).map(x=>`<tr><td>${esc(x.name)}</td><td class="num">${fmt(x.good)}</td><td class="num">${fmt(x.reject)}</td><td class="num">${fmt(x.good+x.reject)}</td></tr>`).join('')||'<tr><td colspan="4">Belum ada data</td></tr>'}</tbody></table><h2>Detail Produksi</h2><table class="compact"><thead><tr><th>Tanggal</th><th>Produk</th><th class="num">Good</th><th class="num">Reject</th><th>Catatan / Batch</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${dateID(x.date)}</td><td>${esc(x.productName)}</td><td class="num">${fmt(x.qty)}</td><td class="num">${fmt(x.reject)}</td><td>${esc(x.note||'-')}</td></tr>`).join('')||'<tr><td colspan="5">Belum ada data</td></tr>'}</tbody></table>`,'report')}


window.printCostingReport=()=>{
 const rows=db.products.map(p=>{
   const pack=Math.max(1,Number(p.packSize||1));
   const hppPcs=Number(p.hpp||0),hppPack=hppPcs*pack;
   const regPcs=Number(p.priceRegular||0),resPcs=Number(p.priceReseller||0);
   const regPack=Number(p.priceRegularPack||0) || regPcs*pack;
   const resPack=Number(p.priceResellerPack||0) || resPcs*pack;
   const regProfitPcs=regPcs-hppPcs,resProfitPcs=resPcs-hppPcs;
   const regProfitPack=regPack-hppPack,resProfitPack=resPack-hppPack;
   return {name:p.name,pack,hppPcs,hppPack,regPcs,resPcs,regPack,resPack,regProfitPcs,resProfitPcs,regProfitPack,resProfitPack,
     regMarginPcs:regPcs?regProfitPcs/regPcs*100:0,resMarginPcs:resPcs?resProfitPcs/resPcs*100:0,
     regMarginPack:regPack?regProfitPack/regPack*100:0,resMarginPack:resPack?resProfitPack/resPack*100:0};
 });
 const avg=(key)=>rows.length?rows.reduce((a,x)=>a+Number(x[key]||0),0)/rows.length:0;
 const body=`<h2>LAPORAN COSTING</h2><div class="muted">Berdasarkan Master Produk • Dicetak: ${new Date().toLocaleString('id-ID')}</div>
 <div class="summary"><div class="box"><b>${rows.length}</b>Total Produk</div><div class="box"><b>${money(avg('hppPcs'))}</b>Rata-rata HPP / Pcs</div><div class="box"><b>${avg('regMarginPcs').toFixed(1)}%</b>Rata-rata Margin Reguler</div></div>
 <h2>Costing Dasar</h2><table class="compact"><thead><tr><th>Produk</th><th class="num">Isi / Pack</th><th class="num">HPP / Pcs</th><th class="num">HPP / Pack</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.name)}</td><td class="num">${fmt(x.pack)} Pcs</td><td class="num">${money(x.hppPcs)}</td><td class="num">${money(x.hppPack)}</td></tr>`).join('')||'<tr><td colspan="4">Belum ada produk</td></tr>'}</tbody></table>
 <h2>Harga & Margin per Pcs</h2><table class="compact"><thead><tr><th>Produk</th><th class="num">Harga Reguler</th><th class="num">Profit Reguler</th><th class="num">Margin</th><th class="num">Harga Reseller</th><th class="num">Profit Reseller</th><th class="num">Margin</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.name)}</td><td class="num">${money(x.regPcs)}</td><td class="num">${money(x.regProfitPcs)}</td><td class="num">${x.regMarginPcs.toFixed(1)}%</td><td class="num">${money(x.resPcs)}</td><td class="num">${money(x.resProfitPcs)}</td><td class="num">${x.resMarginPcs.toFixed(1)}%</td></tr>`).join('')||'<tr><td colspan="7">Belum ada produk</td></tr>'}</tbody></table>
 <h2>Harga & Margin per Pack</h2><table class="compact"><thead><tr><th>Produk</th><th class="num">Harga Reguler</th><th class="num">Profit Reguler</th><th class="num">Margin</th><th class="num">Harga Reseller</th><th class="num">Profit Reseller</th><th class="num">Margin</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.name)}</td><td class="num">${money(x.regPack)}</td><td class="num">${money(x.regProfitPack)}</td><td class="num">${x.regMarginPack.toFixed(1)}%</td><td class="num">${money(x.resPack)}</td><td class="num">${money(x.resProfitPack)}</td><td class="num">${x.resMarginPack.toFixed(1)}%</td></tr>`).join('')||'<tr><td colspan="7">Belum ada produk</td></tr>'}</tbody></table>
 <p class="muted" style="margin-top:12px">Catatan: HPP menggunakan nilai HPP / Pcs pada Master Produk. HPP / Pack = HPP / Pcs × Isi / Pack.</p>`;
 printWindow('Laporan Costing',body,'report');
}


/* ===== V4.8 Costing per Produk (batch sebagai data internal) ===== */
let prodRawDraft=[];
let prodPackDraft=[];
let costingActiveTab='product';
let costingSelectedProductId='';

function migrateCostingData(data){
  if(!data||typeof data!=='object') return data;
  data.productions=Array.isArray(data.productions)?data.productions:[];
  const daily={};
  data.productions.forEach((p,idx)=>{
    p.rawMaterialUsage=Array.isArray(p.rawMaterialUsage)?p.rawMaterialUsage:[];
    p.packagingUsage=Array.isArray(p.packagingUsage)?p.packagingUsage:[];
    p.otherCosts=Object.assign({gas:0,listrik:0,tenagaKerja:0,ongkosProduksi:0,lainnya:0},p.otherCosts||{});
    p.outputUnit=(String(p.outputUnit||'PCS').toUpperCase()==='PACK')?'PACK':'PCS';
    p.outputQty=Number(p.outputQty)||Number(p.qty)||0;
    p.packSize=Math.max(1,Number(p.packSize)||Number((data.products||[]).find(x=>x.id===p.productId)?.packSize)||1);
    if(!p.no){
      const k=p.date||'legacy'; daily[k]=(daily[k]||0)+1;
      const d=String(p.date||'').replaceAll('-','').slice(2) || String(idx+1).padStart(6,'0');
      p.no=`PR-${d}-${String(daily[k]).padStart(3,'0')}`;
    }
  });
  return data;
}
function nextProductionNo(date){
  const key=String(date||today()).replaceAll('-','').slice(2);
  const prefix=`PR-${key}-`;
  let max=0;
  db.productions.forEach(p=>{if(String(p.no||'').startsWith(prefix)){max=Math.max(max,Number(String(p.no).split('-').pop())||0)}});
  return prefix+String(max+1).padStart(3,'0');
}
function otherCostTotal(o){return ['gas','listrik','tenagaKerja','ongkosProduksi','lainnya'].reduce((s,k)=>s+Number(o?.[k]||0),0)}
function batchCosting(p){
  const raw=(p.rawMaterialUsage||[]).map(x=>({...x,unitCost:Number(x.unitCost??x.cost??0),cost:Number(x.cost??(Number(x.qty||0)*Number(x.unitCost??0)))}));
  const pack=(p.packagingUsage||[]).map(x=>({...x,unitCost:Number(x.unitCost??x.cost??0),cost:Number(x.cost??(Number(x.qty||0)*Number(x.unitCost??0)))}));
  // Kompatibilitas: bila snapshot belum ada, baca transaksi OUT yang sudah terhubung ke batch.
  if(!raw.length){db.materialTx.filter(t=>t.mode==='OUT'&&t.productionId===p.id).forEach(t=>raw.push({itemId:t.itemId,name:t.itemName,qty:Number(t.qty||0),unit:t.unit||db.materials.find(x=>x.id===t.itemId)?.unit||'',unitCost:Number(t.cost||0),cost:Number(t.qty||0)*Number(t.cost||0)}))}
  if(!pack.length){db.packagingTx.filter(t=>t.mode==='OUT'&&t.productionId===p.id).forEach(t=>pack.push({itemId:t.itemId,name:t.itemName,qty:Number(t.qty||0),unit:t.unit||db.packaging.find(x=>x.id===t.itemId)?.unit||'',unitCost:Number(t.cost||0),cost:Number(t.qty||0)*Number(t.cost||0)}))}
  const rawTotal=raw.reduce((s,x)=>s+Number(x.cost||0),0);
  const packTotal=pack.reduce((s,x)=>s+Number(x.cost||0),0);
  const other=Object.assign({gas:0,listrik:0,tenagaKerja:0,ongkosProduksi:0,lainnya:0},p.otherCosts||{});
  const otherTotal=otherCostTotal(other);
  const total=rawTotal+packTotal+otherTotal;
  const qtyPcs=Number(p.qty||0);
  const outputUnit=(String(p.outputUnit||'PCS').toUpperCase()==='PACK')?'PACK':'PCS';
  const outputQty=Number(p.outputQty)||(outputUnit==='PACK'?qtyPcs/Math.max(1,Number(p.packSize||1)):qtyPcs);
  const hppUnit=outputQty>0?total/outputQty:0;
  const ready=(raw.length+pack.length>0)||otherTotal>0;
  return {raw,pack,other,rawTotal,packTotal,otherTotal,total,qtyPcs,outputQty,outputUnit,hppUnit,ready};
}
function marginPct(price,hpp){return Number(price)>0?((Number(price)-Number(hpp))/Number(price)*100):0}
function productPriceForUnit(prod,unit){const isPack=unit==='PACK';return {regular:isPack?(Number(prod?.priceRegularPack)||Number(prod?.priceRegular||0)*Math.max(1,Number(prod?.packSize||1))):Number(prod?.priceRegular||0),reseller:isPack?(Number(prod?.priceResellerPack)||Number(prod?.priceReseller||0)*Math.max(1,Number(prod?.packSize||1))):Number(prod?.priceReseller||0)}}
function costingStatus(p){const c=batchCosting(p);return c.ready?'<span class="badge ok">Siap</span>':'<span class="badge bad">Belum lengkap</span>'}

function productionUsageOptions(kind){const arr=kind==='raw'?db.materials:db.packaging;return arr.map(x=>`<option value="${x.id}">${esc(x.name)}${kind==='pack'?' - '+packTypeLabel(x.type):''} | stok ${fmt(x.stock)} ${esc(x.unit)}</option>`).join('')}
function renderProdUsageDraft(){
  const make=(arr,kind)=>arr.length?`<div class="tablewrap fit"><table><thead><tr><th>Item</th><th class="num">Pemakaian</th><th>Satuan</th><th class="num">Cost/Unit</th><th class="num">Biaya</th><th>Aksi</th></tr></thead><tbody>${arr.map((x,i)=>`<tr><td>${esc(x.name)}</td><td class="num">${fmt(x.qty)}</td><td>${esc(x.unit)}</td><td class="num">${money(x.unitCost)}</td><td class="num">${money(x.qty*x.unitCost)}</td><td><button class="btn danger smallbtn" onclick="removeProdUsage('${kind}',${i})">Hapus</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="small">Belum ada pemakaian.</div>';
  const r=$('#prodRawDraft'); if(r)r.innerHTML=make(prodRawDraft,'raw');
  const p=$('#prodPackDraft'); if(p)p.innerHTML=make(prodPackDraft,'pack');
}
window.addProdUsage=kind=>{
  const isRaw=kind==='raw',arr=isRaw?db.materials:db.packaging,draft=isRaw?prodRawDraft:prodPackDraft;
  const id=$(`#p${isRaw?'Raw':'Pack'}Item`)?.value,qty=Number($(`#p${isRaw?'Raw':'Pack'}Qty`)?.value||0),item=arr.find(x=>x.id===id);
  if(!item||qty<=0)return alert('Pilih item dan isi pemakaian.');
  const already=draft.filter(x=>x.itemId===id).reduce((s,x)=>s+Number(x.qty||0),0);
  if(already+qty>Number(item.stock||0))return alert(`Stok ${item.name} tidak cukup. Stok tersedia ${fmt(item.stock)} ${item.unit}.`);
  draft.push({itemId:item.id,name:item.name,qty,unit:item.unit,unitCost:Number(item.avgCost||0),type:item.type||''});
  $(`#p${isRaw?'Raw':'Pack'}Qty`).value='';renderProdUsageDraft();
}
window.loadExistingUsageForProduction=()=>{const date=$('#pDate')?.value||today();const usedIds=new Set([...prodRawDraft,...prodPackDraft].map(x=>x.sourceTxId).filter(Boolean));let added=0;db.materialTx.filter(t=>t.mode==='OUT'&&t.date===date&&!t.productionId&&!usedIds.has(t.id)).forEach(t=>{const item=db.materials.find(x=>x.id===t.itemId);prodRawDraft.push({itemId:t.itemId,name:t.itemName,qty:Number(t.qty||0),unit:t.unit||item?.unit||'',unitCost:Number(t.cost||item?.avgCost||0),sourceTxId:t.id});added++});db.packagingTx.filter(t=>t.mode==='OUT'&&t.date===date&&!t.productionId&&!usedIds.has(t.id)).forEach(t=>{const item=db.packaging.find(x=>x.id===t.itemId);prodPackDraft.push({itemId:t.itemId,name:t.itemName,qty:Number(t.qty||0),unit:t.unit||item?.unit||'',unitCost:Number(t.cost||item?.avgCost||0),type:item?.type||'',sourceTxId:t.id});added++});renderProdUsageDraft();alert(added?`${added} transaksi pemakaian tanggal ${dateID(date)} dimuat. Hapus item yang bukan untuk batch ini sebelum Simpan.`:'Tidak ada transaksi Pemakaian / Keluar yang belum terhubung pada tanggal tersebut.')}
window.removeProdUsage=(kind,i)=>{(kind==='raw'?prodRawDraft:prodPackDraft).splice(i,1);renderProdUsageDraft()}
window.refreshProductionNo=()=>{const el=$('#pNoPreview');if(el)el.value=nextProductionNo($('#pDate')?.value||today())}
window.syncProductionUnit=()=>{const p=db.products.find(x=>x.id===$('#pProduct')?.value),el=$('#pUnitInfo');if(el&&p)el.textContent=`1 Pack = ${fmt(p.packSize||1)} Pcs`}

function renderProduction(){
  const opts=db.products.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');
  $('#production').innerHTML=`<div class="card no-print"><h2>Input Hasil Produksi</h2>
   <div class="row3"><div><label>Tanggal</label><input id="pDate" type="date" value="${today()}" onchange="refreshProductionNo()"></div><div><label>No. Produksi</label><input id="pNoPreview" value="${nextProductionNo(today())}" readonly></div><div><label>Produk</label><select id="pProduct" onchange="syncProductionUnit()">${opts}</select></div><div><label>Hasil Good</label><input id="pQty" type="number" min="0.01" step="0.01"></div><div><label>Satuan Hasil</label><select id="pOutputUnit" onchange="syncProductionUnit()"><option value="PCS">Pcs</option><option value="PACK">Pack</option></select><div id="pUnitInfo" class="small"></div></div><div><label>Reject</label><input id="pReject" type="number" min="0" step="0.01" value="0"></div><div class="full"><label>Catatan / Batch</label><input id="pNote"></div></div><div class="actions"><button class="btn secondary" onclick="loadExistingUsageForProduction()">↙ Ambil transaksi Pemakaian / Keluar tanggal ini</button></div><p class="small">Jika pemakaian sudah dicatat di menu Raw Material / Packaging, gunakan tombol ini agar tidak perlu input ulang. Review item yang terambil sebelum menyimpan batch.</p>
   <h3>Pemakaian Raw Material Aktual</h3><div class="row3"><div><label>Bahan</label><select id="pRawItem">${productionUsageOptions('raw')}</select></div><div><label>Qty Pemakaian</label><input id="pRawQty" type="number" min="0.001" step="0.001"></div><div style="display:flex;align-items:end"><button class="btn secondary" style="width:100%" onclick="addProdUsage('raw')">+ Tambah Bahan</button></div></div><div id="prodRawDraft"></div>
   <h3>Pemakaian Packaging Aktual</h3><div class="row3"><div><label>Packaging</label><select id="pPackItem">${productionUsageOptions('pack')}</select></div><div><label>Qty Pemakaian</label><input id="pPackQty" type="number" min="0.001" step="0.001"></div><div style="display:flex;align-items:end"><button class="btn secondary" style="width:100%" onclick="addProdUsage('pack')">+ Tambah Packaging</button></div></div><div id="prodPackDraft"></div>
   <h3>Biaya Produksi Lainnya</h3><div class="row3"><div><label>Gas</label><input id="pCostGas" type="number" min="0" value="0"></div><div><label>Listrik</label><input id="pCostElectric" type="number" min="0" value="0"></div><div><label>Tenaga Kerja</label><input id="pCostLabor" type="number" min="0" value="0"></div><div><label>Ongkos Produksi</label><input id="pCostProcess" type="number" min="0" value="0"></div><div><label>Biaya Lainnya</label><input id="pCostOther" type="number" min="0" value="0"></div></div>
   <p class="small">Pemakaian yang dimasukkan di sini otomatis menjadi transaksi Pemakaian / Keluar pada Raw Material dan Packaging. Harga costing dibekukan menggunakan Avg Cost persediaan pada saat produksi disimpan.</p><button class="btn" onclick="addProduction()">Simpan Hasil Produksi & Costing</button></div>
   <div class="card"><h2>Rekap Produksi</h2><div class="tablewrap fit"><table><thead><tr><th>Tanggal</th><th>No. Produksi</th><th>Produk</th><th class="num">Good</th><th>Satuan</th><th class="num">Reject</th><th class="num">HPP/Unit</th><th>Status Costing</th><th>Catatan</th><th class="no-print">Aksi</th></tr></thead><tbody>${db.productions.slice().reverse().map(x=>{const c=batchCosting(x);return`<tr><td>${dateID(x.date)}</td><td>${esc(x.no)}</td><td>${esc(x.productName)}</td><td class="num">${fmt(x.outputQty||x.qty)}</td><td>${unitLabel(x.outputUnit)}</td><td class="num">${fmt(x.reject||0)}</td><td class="num">${c.ready?money(c.hppUnit):'-'}</td><td>${costingStatus(x)}</td><td>${esc(x.note||'-')}</td><td class="no-print"><button class="btn secondary smallbtn" onclick="editProduction('${x.id}')">Edit</button> <button class="btn danger smallbtn" onclick="deleteProduction('${x.id}')">Delete</button></td></tr>`}).join('')||'<tr><td colspan="10" class="empty">Belum ada produksi</td></tr>'}</tbody></table></div></div>`;
  setTimeout(()=>{syncProductionUnit();renderProdUsageDraft()},0);
}
window.addProduction=()=>{
  const p=db.products.find(x=>x.id===$('#pProduct')?.value),entered=Number($('#pQty')?.value),outputUnit=$('#pOutputUnit')?.value||'PCS',rejectEntered=Number($('#pReject')?.value||0),date=$('#pDate')?.value||today();
  if(!p||entered<=0)return alert('Qty hasil produksi harus lebih dari 0.');
  if(!prodRawDraft.length&&!prodPackDraft.length&&![Number($('#pCostGas')?.value||0),Number($('#pCostElectric')?.value||0),Number($('#pCostLabor')?.value||0),Number($('#pCostProcess')?.value||0),Number($('#pCostOther')?.value||0)].some(x=>x>0)){if(!confirm('Belum ada pemakaian Raw Material, Packaging, atau biaya lain. Simpan produksi tanpa costing aktual?'))return;}
  for(const u of prodRawDraft){if(u.sourceTxId)continue;const item=db.materials.find(x=>x.id===u.itemId);if(!item||Number(item.stock||0)<Number(u.qty||0))return alert(`Stok ${u.name} tidak cukup.`)}
  for(const u of prodPackDraft){if(u.sourceTxId)continue;const item=db.packaging.find(x=>x.id===u.itemId);if(!item||Number(item.stock||0)<Number(u.qty||0))return alert(`Stok ${u.name} tidak cukup.`)}
  const packSize=Math.max(1,Number(p.packSize||1)),qtyPcs=outputUnit==='PACK'?entered*packSize:entered,rejectPcs=outputUnit==='PACK'?rejectEntered*packSize:rejectEntered,no=nextProductionNo(date),id=uid('P');
  const rawUsage=prodRawDraft.map(u=>({...u,unitCost:u.sourceTxId?Number(u.unitCost||0):Number(db.materials.find(x=>x.id===u.itemId)?.avgCost||u.unitCost||0)})).map(u=>({...u,cost:Number(u.qty)*Number(u.unitCost)}));
  const packagingUsage=prodPackDraft.map(u=>({...u,unitCost:u.sourceTxId?Number(u.unitCost||0):Number(db.packaging.find(x=>x.id===u.itemId)?.avgCost||u.unitCost||0)})).map(u=>({...u,cost:Number(u.qty)*Number(u.unitCost)}));
  const otherCosts={gas:Number($('#pCostGas')?.value||0),listrik:Number($('#pCostElectric')?.value||0),tenagaKerja:Number($('#pCostLabor')?.value||0),ongkosProduksi:Number($('#pCostProcess')?.value||0),lainnya:Number($('#pCostOther')?.value||0)};
  rawUsage.forEach(u=>{const item=db.materials.find(x=>x.id===u.itemId);if(u.sourceTxId){const t=db.materialTx.find(x=>x.id===u.sourceTxId);if(t){t.productionId=id;t.productionNo=no;t.note=t.note||`Produksi ${no} - ${p.name}`;t.cost=Number(t.cost||u.unitCost||0)}}else{item.stock-=Number(u.qty);db.materialTx.push({id:uid('T'),date,itemId:item.id,itemName:item.name,mode:'OUT',qty:Number(u.qty),cost:Number(u.unitCost),unit:item.unit,note:`Produksi ${no} - ${p.name}`,productionId:id,productionNo:no})}});
  packagingUsage.forEach(u=>{const item=db.packaging.find(x=>x.id===u.itemId);if(u.sourceTxId){const t=db.packagingTx.find(x=>x.id===u.sourceTxId);if(t){t.productionId=id;t.productionNo=no;t.note=t.note||`Produksi ${no} - ${p.name}`;t.cost=Number(t.cost||u.unitCost||0)}}else{item.stock-=Number(u.qty);db.packagingTx.push({id:uid('T'),date,itemId:item.id,itemName:item.name,mode:'OUT',qty:Number(u.qty),cost:Number(u.unitCost),unit:item.unit,note:`Produksi ${no} - ${p.name}`,productionId:id,productionNo:no})}});
  db.fgStock[p.id]=(Number(db.fgStock[p.id])||0)+qtyPcs;
  db.productions.push({id,no,date,productId:p.id,productName:p.name,qty:qtyPcs,outputQty:entered,outputUnit,packSize,reject:rejectPcs,rejectOutputQty:rejectEntered,note:$('#pNote')?.value||'',rawMaterialUsage:rawUsage,packagingUsage,otherCosts,costingCaptured:true});
  prodRawDraft=[];prodPackDraft=[];save();
}

window.editProduction=id=>{const p=db.productions.find(x=>x.id===id);if(!p)return;const before=JSON.parse(JSON.stringify(p));const date=prompt('Tanggal produksi (YYYY-MM-DD):',p.date);if(date===null)return;const out=prompt(`Hasil Good (${unitLabel(p.outputUnit)}):`,p.outputQty||p.qty);if(out===null)return;const rej=prompt(`Reject (${unitLabel(p.outputUnit)}):`,p.rejectOutputQty||0);if(rej===null)return;const note=prompt('Catatan / Batch:',p.note||'');if(note===null)return;for(const u of (p.rawMaterialUsage||[])){const q=prompt(`Pemakaian RM - ${u.name} (${u.unit}):`,u.qty);if(q===null)return;u.qty=Number(q)||0;u.cost=u.qty*Number(u.unitCost||0);const t=db.materialTx.find(t=>t.productionId===p.id&&t.itemId===u.itemId);if(t){t.qty=u.qty;t.date=date;t.cost=Number(u.unitCost||t.cost||0)}}for(const u of (p.packagingUsage||[])){const q=prompt(`Pemakaian Packaging - ${u.name} (${u.unit}):`,u.qty);if(q===null)return;u.qty=Number(q)||0;u.cost=u.qty*Number(u.unitCost||0);const t=db.packagingTx.find(t=>t.productionId===p.id&&t.itemId===u.itemId);if(t){t.qty=u.qty;t.date=date;t.cost=Number(u.unitCost||t.cost||0)}}const oc=p.otherCosts||{};for(const [k,label] of [['gas','Gas'],['listrik','Listrik'],['tenagaKerja','Tenaga Kerja'],['ongkosProduksi','Ongkos Produksi'],['lainnya','Biaya Lainnya']]){const v=prompt(label+':',Number(oc[k]||0));if(v===null)return;oc[k]=Number(v)||0}p.otherCosts=oc;p.date=date;p.outputQty=Number(out)||0;p.rejectOutputQty=Number(rej)||0;p.qty=(String(p.outputUnit).toUpperCase()==='PACK'?p.outputQty*Number(p.packSize||1):p.outputQty);p.reject=(String(p.outputUnit).toUpperCase()==='PACK'?p.rejectOutputQty*Number(p.packSize||1):p.rejectOutputQty);p.note=note;recalcAll();audit('Produksi','EDIT',p.no,before,p,'Koreksi hasil produksi/costing');save()}
window.deleteProduction=id=>{const p=db.productions.find(x=>x.id===id);if(!p)return;if(!confirm(`Hapus produksi ${p.no}? Pemakaian terkait, stok FG, dan costing akan dihitung ulang.`))return;const before=JSON.parse(JSON.stringify(p));db.materialTx=db.materialTx.filter(t=>t.productionId!==id);db.packagingTx=db.packagingTx.filter(t=>t.productionId!==id);db.productions=db.productions.filter(x=>x.id!==id);recalcAll();audit('Produksi','DELETE',p.no,before,null,'Produksi dihapus');save()}

// Transaksi manual tetap tersedia. Untuk Pemakaian / Keluar, cost snapshot memakai Avg Cost persediaan saat transaksi disimpan.
window.addTx=kind=>{let isRM=kind==='material',arr=isRM?db.materials:db.packaging,txs=isRM?db.materialTx:db.packagingTx,item=arr.find(x=>x.id===$(`#${kind}Item`).value),mode=$(`#${kind}Mode`).value,qty=Number($(`#${kind}Qty`).value),inputCost=Number($(`#${kind}Cost`).value||0);if(!item||qty<=0)return alert('Pilih item dan isi qty.');if(mode==='OUT'&&Number(item.stock||0)<qty)return alert('Stok tidak cukup.');let cost=inputCost;if(mode==='IN'){let oldVal=Number(item.stock||0)*Number(item.avgCost||0),newVal=qty*inputCost;item.stock=Number(item.stock||0)+qty;item.avgCost=item.stock?((oldVal+newVal)/item.stock):0}else{cost=Number(item.avgCost||0);item.stock=Number(item.stock||0)-qty}txs.push({id:uid('T'),date:$(`#${kind}Date`).value,itemId:item.id,itemName:item.name,mode,qty,cost,unit:item.unit,note:$(`#${kind}Note`).value});save()}

function costingProductOptions(allLabel='Semua Produk'){return `<option value="ALL">${allLabel}</option>`+db.products.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}
function costingNoOptions(){return `<option value="ALL">Semua No. Produksi</option>`+db.productions.slice().reverse().map(p=>`<option value="${p.id}">${esc(p.no)} - ${esc(p.productName)}</option>`).join('')}
function filteredCostingBatches(from,to,productId,noId){return db.productions.filter(p=>(!from||p.date>=from)&&(!to||p.date<=to)&&(productId==='ALL'||!productId||p.productId===productId)&&(noId==='ALL'||!noId||p.id===noId)).sort((a,b)=>(b.date||'').localeCompare(a.date||'')||String(b.no||'').localeCompare(String(a.no||'')))}
function usageCostTable(title,rows,total){return`<h3>${title}</h3><div class="tablewrap fit"><table><thead><tr><th>${title.includes('Packaging')?'Packaging':'Bahan'}</th><th class="num">Pemakaian</th><th>Satuan</th><th class="num">Harga Satuan</th><th class="num">Biaya</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.name||x.itemName)}</td><td class="num">${fmt(x.qty)}</td><td>${esc(x.unit||'-')}</td><td class="num">${money(x.unitCost||0)}</td><td class="num">${money(x.cost||0)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Tidak ada pemakaian</td></tr>'}<tr><td colspan="4"><b>Total ${title.replace('Biaya ','')}</b></td><td class="num"><b>${money(total)}</b></td></tr></tbody></table></div>`}
function costingInfo(p,c){const prod=db.products.find(x=>x.id===p.productId),weight=Number(prod?.packWeight||0),weightUnit=prod?.weightUnit||'gram',packs=c.outputUnit==='PACK'?c.outputQty:(Number(p.qty||0)/Math.max(1,Number(p.packSize||1))),totalWeight=weight>0?packs*weight:0;return`<div class="grid3"><div class="kpi"><b>${dateID(p.date)}</b><span>Tanggal Produksi</span></div><div class="kpi"><b>${esc(p.no)}</b><span>No. Produksi</span></div><div class="kpi"><b>${esc(p.productName)}</b><span>Produk</span></div><div class="kpi"><b>${fmt(c.outputQty)} ${unitLabel(c.outputUnit)}</b><span>Hasil Aktual</span></div><div class="kpi"><b>${p.packSize?fmt(p.packSize)+' Pcs':'-'}</b><span>Isi / Pack</span></div><div class="kpi"><b>${totalWeight?fmt(totalWeight)+' '+esc(weightUnit):'-'}</b><span>Total Berat</span></div></div>`}
function costingOtherTable(c){const items=[['Gas',c.other.gas],['Listrik',c.other.listrik],['Tenaga kerja',c.other.tenagaKerja],['Ongkos produksi',c.other.ongkosProduksi],['Biaya lainnya',c.other.lainnya]];return`<h3>Biaya Produksi Lainnya</h3><div class="tablewrap fit"><table><thead><tr><th>Komponen</th><th class="num">Biaya</th></tr></thead><tbody>${items.map(x=>`<tr><td>${x[0]}</td><td class="num">${money(x[1])}</td></tr>`).join('')}<tr><td><b>Total Biaya Lainnya</b></td><td class="num"><b>${money(c.otherTotal)}</b></td></tr></tbody></table></div>`}
function costingSummaryTable(p,c){return`<h3>Ringkasan Costing</h3><div class="tablewrap fit"><table><tbody><tr><td>Raw Material</td><td class="num">${money(c.rawTotal)}</td></tr><tr><td>Packaging</td><td class="num">${money(c.packTotal)}</td></tr><tr><td>Biaya Produksi Lainnya</td><td class="num">${money(c.otherTotal)}</td></tr><tr class="cost-total"><td><b>TOTAL BIAYA PRODUKSI</b></td><td class="num"><b>${money(c.total)}</b></td></tr><tr><td>Hasil Produksi Aktual</td><td class="num"><b>${fmt(c.outputQty)} ${unitLabel(c.outputUnit)}</b></td></tr><tr class="cost-hpp"><td><b>HPP / ${unitLabel(c.outputUnit)}</b></td><td class="num"><b>${money(c.hppUnit)}</b></td></tr></tbody></table></div>`}
function costingMarginTable(p,c){const prod=db.products.find(x=>x.id===p.productId),pr=productPriceForUnit(prod,c.outputUnit),rM=pr.regular-c.hppUnit,sM=pr.reseller-c.hppUnit;return`<h3>Analisa Harga Jual dan Margin</h3><div class="tablewrap fit"><table><thead><tr><th>Kategori</th><th class="num">Harga Jual</th><th class="num">HPP</th><th class="num">Margin Rp</th><th class="num">Margin %</th></tr></thead><tbody><tr><td>Reguler</td><td class="num">${money(pr.regular)}</td><td class="num">${money(c.hppUnit)}</td><td class="num">${money(rM)}</td><td class="num">${marginPct(pr.regular,c.hppUnit).toFixed(1)}%</td></tr><tr><td>Reseller</td><td class="num">${money(pr.reseller)}</td><td class="num">${money(c.hppUnit)}</td><td class="num">${money(sM)}</td><td class="num">${marginPct(pr.reseller,c.hppUnit).toFixed(1)}%</td></tr></tbody></table></div>`}
function costingPrintSection(title,html,keep=false){return`<section class="cost-section ${keep?'keep-block':''}"><h3>${title}</h3>${html}</section>`}
function usageCostTablePrint(title,rows,total){const label=title.includes('Packaging')?'Packaging':'Bahan';return costingPrintSection(title,`<table><thead><tr><th>${label}</th><th class="num">Pemakaian</th><th>Satuan</th><th class="num">Harga Satuan</th><th class="num">Biaya</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.name||x.itemName)}</td><td class="num">${fmt(x.qty)}</td><td>${esc(x.unit||'-')}</td><td class="num">${money(x.unitCost||0)}</td><td class="num">${money(x.cost||0)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Tidak ada pemakaian</td></tr>'}<tr class="cost-total"><td colspan="4"><b>Total ${title.replace('Biaya ','')}</b></td><td class="num"><b>${money(total)}</b></td></tr></tbody></table>`,rows.length<=8)}
function costingOtherPrint(c){const items=[['Gas',c.other.gas],['Listrik',c.other.listrik],['Tenaga kerja',c.other.tenagaKerja],['Ongkos produksi',c.other.ongkosProduksi],['Biaya lainnya',c.other.lainnya]];return costingPrintSection('Biaya Produksi Lainnya',`<table><thead><tr><th>Komponen</th><th class="num">Biaya</th></tr></thead><tbody>${items.map(x=>`<tr><td>${x[0]}</td><td class="num">${money(x[1])}</td></tr>`).join('')}<tr class="cost-total"><td><b>Total Biaya Lainnya</b></td><td class="num"><b>${money(c.otherTotal)}</b></td></tr></tbody></table>`,true)}
function costingSummaryPrint(p,c){return costingPrintSection('Ringkasan Costing',`<table><tbody><tr><td>Raw Material</td><td class="num">${money(c.rawTotal)}</td></tr><tr><td>Packaging</td><td class="num">${money(c.packTotal)}</td></tr><tr><td>Biaya Produksi Lainnya</td><td class="num">${money(c.otherTotal)}</td></tr><tr class="cost-total"><td><b>TOTAL BIAYA PRODUKSI</b></td><td class="num"><b>${money(c.total)}</b></td></tr><tr><td>Hasil Produksi Aktual</td><td class="num"><b>${fmt(c.outputQty)} ${unitLabel(c.outputUnit)}</b></td></tr><tr class="cost-hpp"><td><b>HPP / ${unitLabel(c.outputUnit)}</b></td><td class="num"><b>${money(c.hppUnit)}</b></td></tr></tbody></table>`,true)}
function costingMarginPrint(p,c){const prod=db.products.find(x=>x.id===p.productId),pr=productPriceForUnit(prod,c.outputUnit),rM=pr.regular-c.hppUnit,sM=pr.reseller-c.hppUnit;return costingPrintSection('Analisa Harga Jual dan Margin',`<table><thead><tr><th>Kategori</th><th class="num">Harga Jual</th><th class="num">HPP</th><th class="num">Margin Rp</th><th class="num">Margin %</th></tr></thead><tbody><tr><td>Reguler</td><td class="num">${money(pr.regular)}</td><td class="num">${money(c.hppUnit)}</td><td class="num">${money(rM)}</td><td class="num">${marginPct(pr.regular,c.hppUnit).toFixed(1)}%</td></tr><tr><td>Reseller</td><td class="num">${money(pr.reseller)}</td><td class="num">${money(c.hppUnit)}</td><td class="num">${money(sM)}</td><td class="num">${marginPct(pr.reseller,c.hppUnit).toFixed(1)}%</td></tr></tbody></table>`,true)}

function costingBatchDetailHtml(p,screen=true){const c=batchCosting(p);return`<div class="${screen?'card':''}">${screen?`<div class="cardhead"><h2>Costing Batch ${esc(p.no)}</h2><button class="btn secondary" onclick="printCostingBatch('${p.id}')">🖨 Print</button></div>`:''}${!c.ready?'<div class="cost-warning">Batch lama ini belum mempunyai pemakaian/cost snapshot yang terhubung. HPP aktual belum dapat dihitung.</div>':''}${costingInfo(p,c)}${usageCostTable('Biaya Raw Material',c.raw,c.rawTotal)}${usageCostTable('Biaya Packaging',c.pack,c.packTotal)}${costingOtherTable(c)}${costingSummaryTable(p,c)}${costingMarginTable(p,c)}</div>`}
function costingProductMetrics(from,to,pid='ALL'){
  const batches=filteredCostingBatches(from,to,pid||'ALL','ALL').filter(p=>batchCosting(p).ready),map={};
  batches.forEach(p=>{
    const c=batchCosting(p),k=p.productId,prod=db.products.find(x=>x.id===k)||{id:k,name:p.productName,packSize:p.packSize||1};
    if(!map[k])map[k]={product:prod,batches:[],qtyPcs:0,total:0,raw:0,packaging:0,other:0};
    const x=map[k];x.batches.push(p);x.qtyPcs+=Number(c.qtyPcs||0);x.total+=Number(c.total||0);x.raw+=Number(c.rawTotal||0);x.packaging+=Number(c.packTotal||0);x.other+=Number(c.otherTotal||0);
  });
  return Object.values(map).map(x=>{
    const packSize=Math.max(1,Number(x.product.packSize||1)),usePack=packSize>1,unit=usePack?'Pack':'Pcs',qtyUnit=usePack?x.qtyPcs/packSize:x.qtyPcs,hpp=qtyUnit?x.total/qtyUnit:0;
    const prices=productPriceForUnit(x.product,usePack?'PACK':'PCS'),reg=Number(prices.regular||0),res=Number(prices.reseller||0);
    return {...x,packSize,usePack,unit,qtyUnit,hpp,reg,res,regMarginRp:reg-hpp,resMarginRp:res-hpp,regMargin:marginPct(reg,hpp),resMargin:marginPct(res,hpp)};
  }).sort((a,b)=>b.total-a.total||String(a.product.name).localeCompare(String(b.product.name)));
}
function costingProductRows(from,to,pid){return costingProductMetrics(from,to,pid)}
function costingProductSummaryHtml(from,to,pid,screen=true){
  const rows=costingProductMetrics(from,to,pid),totCost=rows.reduce((s,x)=>s+x.total,0),totQty=rows.reduce((s,x)=>s+x.qtyUnit,0);
  return `<div class="${screen?'card':''}">${screen?'<div class="cardhead"><h2>Costing per Produk</h2><button class="btn secondary" onclick="printCostingProduct()">🖨 Print Costing Produk</button></div>':''}<div class="small">HPP rata-rata menggunakan weighted average: Total biaya seluruh batch ÷ total hasil produksi aktual.</div><div class="tablewrap fit"><table><thead><tr><th>Produk</th><th class="num">Qty Produksi</th><th class="num">Total Biaya</th><th class="num">HPP Rata-rata</th><th class="num">Harga Reguler</th><th class="num">Margin Reguler</th><th class="num">Harga Reseller</th><th class="num">Margin Reseller</th>${screen?'<th>Aksi</th>':''}</tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.product.name)}</td><td class="num">${fmt(x.qtyUnit)} ${x.unit}</td><td class="num">${money(x.total)}</td><td class="num"><b>${money(x.hpp)} / ${x.unit}</b></td><td class="num">${money(x.reg)} / ${x.unit}</td><td class="num">${money(x.regMarginRp)} (${x.regMargin.toFixed(1)}%)</td><td class="num">${money(x.res)} / ${x.unit}</td><td class="num">${money(x.resMarginRp)} (${x.resMargin.toFixed(1)}%)</td>${screen?`<td><button class="btn secondary smallbtn" onclick="showCostingProductDetail('${x.product.id}')">Detail</button></td>`:''}</tr>`).join('')||`<tr><td colspan="${screen?9:8}" class="empty">Belum ada produksi dengan costing lengkap pada periode ini.</td></tr>`}${rows.length?`<tr class="cost-total"><td><b>TOTAL</b></td><td class="num"><b>${fmt(totQty)}</b></td><td class="num"><b>${money(totCost)}</b></td><td colspan="${screen?6:5}"></td></tr>`:''}</tbody></table></div>${screen?'<div id="costProductDetail"></div>':''}</div>`;
}
function costingProductFilters(){const now=today(),start=now.slice(0,8)+'01';return`<div class="row3"><div><label>Dari</label><input id="cProdFrom" type="date" value="${start}"></div><div><label>Sampai</label><input id="cProdTo" type="date" value="${now}"></div><div><label>Produk</label><select id="cProdProduct">${costingProductOptions()}</select></div></div><div class="actions"><button class="btn" onclick="applyCostingProduct()">Tampilkan</button><button class="btn secondary" onclick="printCostingProduct()">🖨 Print Costing Produk</button></div><div id="costingProductResult"></div>`}
function costingPanelHtml(){return`<div class="card no-print"><h2>Costing</h2><p class="small">Costing per Produk menggunakan biaya aktual setiap produksi/batch sebagai dasar weighted average. Tidak diperlukan input costing ulang.</p>${costingProductFilters()}</div>`}
window.applyCostingProduct=()=>{const f=$('#cProdFrom')?.value||'',to=$('#cProdTo')?.value||today(),pid=$('#cProdProduct')?.value||'ALL',el=$('#costingProductResult');if(el)el.innerHTML=costingProductSummaryHtml(f,to,pid,true)}
window.showCostingProductDetail=id=>{
  costingSelectedProductId=id;const f=$('#cProdFrom')?.value||'',to=$('#cProdTo')?.value||today(),m=costingProductMetrics(f,to,id)[0],el=$('#costProductDetail');if(!el)return;
  if(!m){el.innerHTML='<div class="empty">Belum ada riwayat costing.</div>';return}
  const rows=m.batches.slice().sort((a,b)=>(a.date||'').localeCompare(b.date||'')||String(a.no||'').localeCompare(String(b.no||'')));
  el.innerHTML=`<div class="card" style="margin-top:16px"><h3>Detail Costing per Produk - ${esc(m.product.name)}</h3><div class="grid3"><div class="kpi"><b>${fmt(m.qtyUnit)} ${m.unit}</b><span>Total Produksi</span></div><div class="kpi"><b>${money(m.total)}</b><span>Total Biaya Produksi</span></div><div class="kpi"><b>${money(m.hpp)} / ${m.unit}</b><span>HPP Rata-rata</span></div><div class="kpi"><b>${fmt(m.packSize)} Pcs</b><span>Isi / Pack</span></div></div><div class="tablewrap fit"><table><thead><tr><th>Tanggal Produksi</th><th>No. Produksi</th><th class="num">Qty Produksi</th><th class="num">Raw Material</th><th class="num">Packaging</th><th class="num">Biaya Lain</th><th class="num">Total Biaya</th><th class="num">HPP / ${m.unit}</th></tr></thead><tbody>${rows.map(p=>{const c=batchCosting(p),q=m.usePack?Number(c.qtyPcs||0)/m.packSize:Number(c.qtyPcs||0),hpp=q?c.total/q:0;return`<tr><td>${dateID(p.date)}</td><td>${esc(p.no)}</td><td class="num">${fmt(q)} ${m.unit}</td><td class="num">${money(c.rawTotal)}</td><td class="num">${money(c.packTotal)}</td><td class="num">${money(c.otherTotal)}</td><td class="num">${money(c.total)}</td><td class="num"><b>${money(hpp)}</b></td></tr>`}).join('')}</tbody></table></div><div class="small" style="margin-top:8px"><b>Perhitungan HPP rata-rata:</b> ${money(m.total)} ÷ ${fmt(m.qtyUnit)} ${m.unit} = <b>${money(m.hpp)} / ${m.unit}</b></div></div>`;
}
function costingPrintStyles(){return`<style>
.cost-product-print{font-size:9px}.cost-product-print h2{font-size:17px;margin:4px 0 2px}.cost-product-print h3{font-size:11px;margin:10px 0 4px}.cost-product-print .meta{font-size:8px;color:#666;margin-bottom:8px}.cost-product-print .info{display:grid;grid-template-columns:1fr 1fr;gap:4px 16px;border:1px solid #bbb;border-radius:5px;padding:7px 9px;margin:8px 0}.cost-product-print table{width:100%;max-width:100%;table-layout:auto;margin-top:4px;font-size:8px}.cost-product-print th,.cost-product-print td{padding:3px 4px;line-height:1.2}.cost-product-print th{background:#fff0ee;text-align:center;vertical-align:middle}.cost-product-print td.num,.cost-product-print th.num{text-align:right;white-space:nowrap}.cost-product-print .total-row td{background:#fff4df;font-weight:700}.cost-product-print .product-block{break-inside:avoid;page-break-inside:avoid;margin-top:11px}.cost-product-print .product-title{border:1px solid #bbb;border-radius:4px;padding:5px 8px;font-size:11px;font-weight:700;margin-bottom:5px;background:#fffaf8}.cost-product-print .product-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:4px;margin:5px 0}.cost-product-print .product-kpis>div{border:1px solid #bbb;border-radius:4px;padding:5px 6px}.cost-product-print .product-kpis b{display:block;font-size:10px}.cost-product-print .formula{border:1px solid #ccc;border-radius:4px;padding:5px 7px;margin-top:5px;font-size:8px}.cost-product-print .notes{border:1px solid #bbb;border-radius:4px;padding:7px 9px;margin-top:10px;font-size:8px}.cost-product-print .good-margin{font-weight:700}.cost-product-print .summary-title{font-size:12px;font-weight:700;margin:8px 0 4px}.cost-product-print .page2{page-break-before:always;break-before:page}.cost-product-print .page2-head{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:1px solid #555;padding-bottom:5px;margin-bottom:8px}.cost-product-print .page2-head h2{margin:0;font-size:15px;text-align:right}.cost-product-print .detail-cost-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;align-items:start}.cost-product-print .detail-cost-box{break-inside:avoid;page-break-inside:avoid}.cost-product-print .detail-cost-box h3{margin:6px 0 3px}.cost-product-print .cost-highlight td{background:#eef8ea;font-weight:700}.cost-product-print .detail-summary{max-width:55%;margin-bottom:6px}.cost-product-print .section-note{font-size:7.6px;color:#666;margin:2px 0 5px}@media print{.cost-product-print{font-size:8px}.cost-product-print table{font-size:7.6px}.cost-product-print th,.cost-product-print td{padding:2.5px 3px}.cost-product-print .product-block{break-inside:avoid;page-break-inside:avoid}.cost-product-print .page2{page-break-before:always;break-before:page}.cost-product-print .detail-cost-grid{grid-template-columns:1fr 1fr;gap:6px}.cost-product-print .detail-cost-box{break-inside:avoid;page-break-inside:avoid}}
</style>`}
function costingAggregateDetail(m){
  const rawMap={},packMap={};
  m.batches.forEach(p=>{const c=batchCosting(p);c.raw.forEach(x=>{const k=x.itemId||x.name||x.itemName||'raw';if(!rawMap[k])rawMap[k]={name:x.name||x.itemName||'-',unit:x.unit||'-',qty:0,cost:0};rawMap[k].qty+=Number(x.qty||0);rawMap[k].cost+=Number(x.cost||0)});c.pack.forEach(x=>{const k=x.itemId||x.name||x.itemName||'pack';if(!packMap[k])packMap[k]={name:x.name||x.itemName||'-',unit:x.unit||'-',qty:0,cost:0};packMap[k].qty+=Number(x.qty||0);packMap[k].cost+=Number(x.cost||0)})});
  const other=[['Gas',0],['Listrik',0],['Tenaga Kerja',0],['Ongkos Produksi',0],['Biaya Lainnya',0]];
  m.batches.forEach(p=>{const c=batchCosting(p);other[0][1]+=Number(c.other.gas||0);other[1][1]+=Number(c.other.listrik||0);other[2][1]+=Number(c.other.tenagaKerja||0);other[3][1]+=Number(c.other.ongkosProduksi||0);other[4][1]+=Number(c.other.lainnya||0)});
  return {raw:Object.values(rawMap).sort((a,b)=>b.cost-a.cost||a.name.localeCompare(b.name)),pack:Object.values(packMap).sort((a,b)=>b.cost-a.cost||a.name.localeCompare(b.name)),other};
}
function costingProductPrintBody(f,to,pid){
  const rows=costingProductMetrics(f,to,pid),totalQty=rows.reduce((s,x)=>s+x.qtyUnit,0),productText=pid==='ALL'?'Semua Produk':(db.products.find(x=>x.id===pid)?.name||'-');
  const units=[...new Set(rows.map(x=>x.unit))],totalUnit=units.length===1?units[0]:'Unit';
  const summary=`<div class="summary-title">RINGKASAN COSTING PER PRODUK</div><table><thead><tr><th>No</th><th>Produk</th><th class="num">Qty Produksi</th><th class="num">Total Biaya Produksi</th><th class="num">HPP Rata-rata</th><th class="num">Harga Jual Reguler</th><th colspan="2">Margin Reguler</th><th class="num">Harga Jual Reseller</th><th colspan="2">Margin Reseller</th></tr><tr><th colspan="6"></th><th class="num">Rp</th><th class="num">%</th><th></th><th class="num">Rp</th><th class="num">%</th></tr></thead><tbody>${rows.map((x,i)=>`<tr><td class="center">${i+1}</td><td>${esc(x.product.name)}</td><td class="num">${fmt(x.qtyUnit)} ${x.unit}</td><td class="num">${money(x.total)}</td><td class="num">${money(x.hpp)} / ${x.unit}</td><td class="num">${money(x.reg)} / ${x.unit}</td><td class="num">${money(x.regMarginRp)}</td><td class="num good-margin">${x.regMargin.toFixed(1)}%</td><td class="num">${money(x.res)} / ${x.unit}</td><td class="num">${money(x.resMarginRp)}</td><td class="num good-margin">${x.resMargin.toFixed(1)}%</td></tr>`).join('')||'<tr><td colspan="11">Belum ada costing lengkap.</td></tr>'}${rows.length?`<tr class="total-row"><td colspan="2">TOTAL</td><td class="num">${fmt(totalQty)} ${totalUnit}</td><td class="num">${money(rows.reduce((s,x)=>s+x.total,0))}</td><td colspan="7"></td></tr>`:''}</tbody></table>`;
  const details=rows.map(m=>{const bs=m.batches.slice().sort((a,b)=>(a.date||'').localeCompare(b.date||'')||String(a.no||'').localeCompare(String(b.no||'')));return`<div class="product-block"><div class="product-title">Produk &nbsp;&nbsp;: ${esc(m.product.name)}</div><div class="product-kpis"><div><span>Total Produksi</span><b>${fmt(m.qtyUnit)} ${m.unit}</b></div><div><span>Total Biaya Produksi</span><b>${money(m.total)}</b></div><div><span>HPP Rata-rata / ${m.unit}</span><b>${money(m.hpp)}</b></div><div><span>Isi / Pack</span><b>${fmt(m.packSize)} Pcs</b></div></div><div class="summary-title">RIWAYAT COSTING (PER PRODUKSI / BATCH)</div><table><thead><tr><th>No</th><th>Tanggal Produksi</th><th>No. Produksi</th><th class="num">Qty Produksi (${m.unit})</th><th class="num">Total Raw Material</th><th class="num">Total Packaging</th><th class="num">Biaya Produksi Lainnya</th><th class="num">Total Biaya Produksi</th><th class="num">HPP / ${m.unit} (Aktual)</th></tr></thead><tbody>${bs.map((p,i)=>{const c=batchCosting(p),q=m.usePack?Number(c.qtyPcs||0)/m.packSize:Number(c.qtyPcs||0),hpp=q?c.total/q:0;return`<tr><td class="center">${i+1}</td><td>${dateID(p.date)}</td><td>${esc(p.no)}</td><td class="num">${fmt(q)}</td><td class="num">${money(c.rawTotal)}</td><td class="num">${money(c.packTotal)}</td><td class="num">${money(c.otherTotal)}</td><td class="num">${money(c.total)}</td><td class="num">${money(hpp)}</td></tr>`}).join('')}<tr class="total-row"><td colspan="3">TOTAL / RATA-RATA</td><td class="num">${fmt(m.qtyUnit)}</td><td class="num">${money(m.raw)}</td><td class="num">${money(m.packaging)}</td><td class="num">${money(m.other)}</td><td class="num">${money(m.total)}</td><td class="num">${money(m.hpp)}</td></tr></tbody></table><div class="formula"><b>Keterangan Perhitungan HPP Rata-rata:</b><br>HPP Rata-rata = Total Biaya Produksi Seluruh Batch ÷ Total Qty Produksi<br>= ${money(m.total)} ÷ ${fmt(m.qtyUnit)} ${m.unit} = <b>${money(m.hpp)} / ${m.unit}</b></div></div>`}).join('');
  const page2=rows.map((m,idx)=>{const d=costingAggregateDetail(m),rawRows=d.raw.map((x,i)=>`<tr><td class="center">${i+1}</td><td>${esc(x.name)}</td><td class="num">${fmt(x.qty)}</td><td>${esc(x.unit)}</td><td class="num">${money(x.cost)}</td></tr>`).join('')||'<tr><td colspan="5">Tidak ada data Raw Material</td></tr>',packRows=d.pack.map((x,i)=>`<tr><td class="center">${i+1}</td><td>${esc(x.name)}</td><td class="num">${fmt(x.qty)}</td><td>${esc(x.unit)}</td><td class="num">${money(x.cost)}</td></tr>`).join('')||'<tr><td colspan="5">Tidak ada data Packaging</td></tr>',otherRows=d.other.map((x,i)=>`<tr><td class="center">${i+1}</td><td>${x[0]}</td><td class="num">${money(x[1])}</td></tr>`).join('');return`<div class="product-block"><div class="product-title">${idx+1}. ${esc(m.product.name)}</div><div class="detail-cost-grid"><div class="detail-cost-box"><h3>A. RINGKASAN TOTAL BIAYA PRODUKSI</h3><table class="detail-summary"><tbody><tr><td>Raw Material (Total)</td><td class="num">${money(m.raw)}</td></tr><tr><td>Packaging (Total)</td><td class="num">${money(m.packaging)}</td></tr><tr><td>Biaya Produksi Lainnya (Total)</td><td class="num">${money(m.other)}</td></tr><tr class="total-row"><td>TOTAL BIAYA PRODUKSI</td><td class="num">${money(m.total)}</td></tr><tr><td>Qty Produksi (Total)</td><td class="num">${fmt(m.qtyUnit)} ${m.unit}</td></tr><tr class="cost-highlight"><td>HPP RATA-RATA / ${m.unit.toUpperCase()}</td><td class="num">${money(m.hpp)}</td></tr></tbody></table><div class="formula"><b>Rumus HPP Weighted Average:</b><br>${money(m.total)} ÷ ${fmt(m.qtyUnit)} ${m.unit} = <b>${money(m.hpp)} / ${m.unit}</b></div></div><div class="detail-cost-box"><h3>B. DETAIL RAW MATERIAL (TOTAL)</h3><table><thead><tr><th>No</th><th>Bahan</th><th class="num">Total Pemakaian</th><th>Satuan</th><th class="num">Total Biaya</th></tr></thead><tbody>${rawRows}<tr class="total-row"><td colspan="4">TOTAL RAW MATERIAL</td><td class="num">${money(m.raw)}</td></tr></tbody></table></div><div class="detail-cost-box"><h3>C. DETAIL PACKAGING (TOTAL)</h3><table><thead><tr><th>No</th><th>Packaging</th><th class="num">Total Pemakaian</th><th>Satuan</th><th class="num">Total Biaya</th></tr></thead><tbody>${packRows}<tr class="total-row"><td colspan="4">TOTAL PACKAGING</td><td class="num">${money(m.packaging)}</td></tr></tbody></table></div><div class="detail-cost-box"><h3>D. DETAIL BIAYA PRODUKSI LAINNYA (TOTAL)</h3><table><thead><tr><th>No</th><th>Komponen Biaya</th><th class="num">Total Biaya</th></tr></thead><tbody>${otherRows}<tr class="total-row"><td colspan="2">TOTAL BIAYA PRODUKSI LAINNYA</td><td class="num">${money(m.other)}</td></tr></tbody></table></div></div></div>`}).join('');
  return `${costingPrintStyles()}<div class="cost-product-print"><div style="display:flex;justify-content:space-between;align-items:flex-start"><div></div><div style="text-align:right"><h2>LAPORAN COSTING<br>PER PRODUK</h2><div class="meta">Periode : ${dateID(f)} s.d ${dateID(to)}<br>Dicetak : ${new Date().toLocaleString('id-ID')}</div></div></div><div class="info"><div><b>Periode</b> &nbsp;: ${dateID(f)} s.d ${dateID(to)}</div><div><b>Total Produk</b> &nbsp;: ${rows.length}</div><div><b>Produk</b> &nbsp;: ${esc(productText)}</div><div><b>Total Produksi</b> &nbsp;: ${fmt(totalQty)} ${totalUnit}</div></div>${summary}<div class="summary-title" style="margin-top:12px">DETAIL COSTING PER PRODUK</div>${details}<div class="page2"><div class="page2-head"><div><b>CEMILAN MOMCIP</b><div class="meta">Homemade Snack &amp; Drink With Love<br>0821-1290-2549</div></div><div><h2>LAPORAN COSTING<br>PER PRODUK</h2><div class="meta">DETAIL TOTAL BIAYA PRODUKSI<br>Periode : ${dateID(f)} s.d ${dateID(to)}</div></div></div><div class="summary-title">DETAIL TOTAL BIAYA PRODUKSI</div>${page2}<div class="notes"><b>Catatan:</b><br>- Total Raw Material dan Packaging merupakan akumulasi seluruh batch produk dalam periode terpilih.<br>- Harga bahan dan packaging menggunakan nilai costing/Avg Cost yang tersimpan pada transaksi produksi.<br>- HPP dihitung berdasarkan total biaya produksi dan total hasil produksi aktual.</div></div><div class="notes"><b>Catatan:</b><br>- Harga jual Reguler &amp; Reseller diambil dari Master Produk.<br>- HPP menggunakan biaya aktual persediaan (Avg Cost), biaya packaging, biaya produksi lainnya, dan hasil produksi aktual.<br>- HPP rata-rata dihitung weighted average berdasarkan total biaya seluruh batch dan total hasil produksi.<br>- Costing terbentuk otomatis saat transaksi produksi disimpan.</div></div>`;
}
window.printCostingProduct=()=>{const f=$('#cProdFrom')?.value||$('#rFrom')?.value||today().slice(0,8)+'01',to=$('#cProdTo')?.value||$('#rTo')?.value||today(),pid=$('#cProdProduct')?.value||'ALL';printWindow('Costing per Produk',costingProductPrintBody(f,to,pid),'report')}
window.printCostingReport=window.printCostingProduct;

function renderReports(){let now=new Date(),y=now.getFullYear(),m=String(now.getMonth()+1).padStart(2,'0'),last=String(new Date(y,now.getMonth()+1,0).getDate()).padStart(2,'0');currentReport=salesRange(`${y}-${m}-01`,`${y}-${m}-${last}`);$('#reports').innerHTML=`<div class="card no-print"><h2>Laporan</h2><div class="row3"><div><label>Dari</label><input id="rFrom" type="date" value="${y}-${m}-01"></div><div><label>Sampai</label><input id="rTo" type="date" value="${today()}"></div><div><label>Jenis Order</label><select id="rType"><option value="ALL">Semua</option><option value="REGULER">Reguler</option><option value="RESELLER">Reseller</option></select></div></div><h3>Penjualan</h3><div class="actions"><button class="btn" onclick="applyReport()">Tampilkan</button><button class="btn secondary" onclick="printSummaryReport()">🖨 Ringkasan YTD/MTD</button><button class="btn secondary" onclick="printDetailReport()">🖨 Detail Penjualan</button></div><h3>Laporan Operasional</h3><div class="actions"><button class="btn secondary" onclick="printRawMaterialPurchaseReport()">🖨 Pembelian Raw Material</button><button class="btn secondary" onclick="printPackagingPurchaseReport()">🖨 Pembelian Packaging</button><button class="btn secondary" onclick="printProductionReport()">🖨 Hasil Produksi</button></div><p class="small">Laporan pembelian dan produksi mengikuti filter tanggal Dari–Sampai di atas.</p></div><div id="reportBody">${reportHtml(currentReport)}</div>${costingPanelHtml()}`}
window.printProductionReport=()=>{let f=$('#rFrom')?.value||'',to=$('#rTo')?.value||today(),rows=db.productions.filter(x=>(!f||x.date>=f)&&(!to||x.date<=to)).sort((a,b)=>a.date.localeCompare(b.date)),good=rows.reduce((s,x)=>s+Number(x.qty||0),0),reject=rows.reduce((s,x)=>s+Number(x.reject||0),0),by={};rows.forEach(x=>{let k=x.productId||x.productName;if(!by[k])by[k]={name:x.productName,good:0,reject:0,batches:0};by[k].good+=Number(x.qty||0);by[k].reject+=Number(x.reject||0);by[k].batches++});printWindow('Hasil Produksi',`<h2>LAPORAN HASIL PRODUKSI</h2><div class="muted">Periode: ${f?dateID(f):'Awal data'} s.d. ${to?dateID(to):'Akhir data'}</div><div class="summary"><div class="box"><b>${rows.length}</b>Batch Produksi</div><div class="box"><b>${fmt(good)}</b>Good (Pcs)</div><div class="box"><b>${fmt(reject)}</b>Reject (Pcs)</div></div><h2>Ringkasan per Produk</h2><table class="compact"><thead><tr><th>Produk</th><th class="num">Batch</th><th class="num">Good (Pcs)</th><th class="num">Reject (Pcs)</th><th class="num">Total Proses</th></tr></thead><tbody>${Object.values(by).map(x=>`<tr><td>${esc(x.name)}</td><td class="num">${x.batches}</td><td class="num">${fmt(x.good)}</td><td class="num">${fmt(x.reject)}</td><td class="num">${fmt(x.good+x.reject)}</td></tr>`).join('')||'<tr><td colspan="5">Belum ada data</td></tr>'}</tbody></table><h2>Detail Produksi</h2><table class="compact"><thead><tr><th>Tanggal</th><th>No. Produksi</th><th>Produk</th><th class="num">Hasil</th><th>Satuan</th><th class="num">Good (Pcs)</th><th class="num">Reject (Pcs)</th><th>Status Costing</th><th>Catatan / Batch</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${dateID(x.date)}</td><td>${esc(x.no||'-')}</td><td>${esc(x.productName)}</td><td class="num">${fmt(x.outputQty||x.qty)}</td><td>${unitLabel(x.outputUnit)}</td><td class="num">${fmt(x.qty)}</td><td class="num">${fmt(x.reject)}</td><td>${batchCosting(x).ready?'Siap':'Belum lengkap'}</td><td>${esc(x.note||'-')}</td></tr>`).join('')||'<tr><td colspan="9">Belum ada data</td></tr>'}</tbody></table>`,'report')}

/* ===== akhir V4.6 ===== */


function renderSettings(){
 $('#settings').innerHTML=`<div class="card no-print"><h2>Pengaturan Printer Thermal</h2><div class="row"><div><label>Lebar kertas</label><select id="printWidth"><option value="57" ${getPrintWidth()==='57'?'selected':''}>57 mm</option><option value="75" ${getPrintWidth()==='75'?'selected':''}>75 mm</option><option value="80" ${getPrintWidth()==='80'?'selected':''}>80 mm</option></select></div><div style="display:flex;align-items:end"><button class="btn" style="width:100%" onclick="savePrintWidth()">Simpan Setting Print</button></div></div><p class="small">Dipakai untuk Struk Order dan Outstanding Produksi.</p></div>
 <div class="card"><h2>Master Produk FG</h2><div class="row3 no-print"><input id="mProdName" placeholder="Nama produk"><input id="mProdPack" type="number" min="1" placeholder="Isi / pack (pcs)"><input id="mProdReg" type="number" placeholder="Harga reguler / pcs"><input id="mProdRegPack" type="number" placeholder="Harga reguler / pack"><input id="mProdRes" type="number" placeholder="Harga reseller / pcs"><input id="mProdResPack" type="number" placeholder="Harga reseller / pack"><input id="mProdHpp" type="number" placeholder="HPP / pcs"><input id="mProdMin" type="number" placeholder="Stok minimum (pcs)"><button class="btn" onclick="addMasterProduct()">Tambah Produk</button></div><div class="tablewrap fit"><table><tr><th>Produk</th><th class="num">Isi/Pack</th><th class="num">Reg/Pcs</th><th class="num">Reg/Pack</th><th class="num">Res/Pcs</th><th class="num">Res/Pack</th><th class="num">HPP/Pcs</th><th class="no-print">Aksi</th></tr>${db.products.map(x=>`<tr><td>${esc(x.id)} - ${esc(x.name)}</td><td class="num">${fmt(x.packSize||1)}</td><td class="num">${money(x.priceRegular)}</td><td class="num">${money(x.priceRegularPack)}</td><td class="num">${money(x.priceReseller)}</td><td class="num">${money(x.priceResellerPack)}</td><td class="num">${money(x.hpp)}</td><td class="no-print"><button class="btn secondary smallbtn" onclick="editPackPricing('${x.id}')">Ubah</button> <button class="btn danger smallbtn" onclick="deleteMaster('product','${x.id}')">Delete</button></td></tr>`).join('')}</table></div></div>
 <div class="card"><h2>Master Raw Material</h2><div class="row3 no-print"><input id="mRMName" placeholder="Nama raw material"><input id="mRMUnit" placeholder="Satuan"><input id="mRMMin" type="number" placeholder="Stok minimum"><button class="btn" onclick="addMasterRM()">Tambah RM</button></div><div class="tablewrap fit"><table><tr><th>Kode</th><th>Item</th><th>Satuan</th><th class="num">Min</th><th class="no-print">Aksi</th></tr>${db.materials.map(x=>`<tr><td>${esc(x.id)}</td><td>${esc(x.name)}</td><td>${esc(x.unit)}</td><td class="num">${fmt(x.minStock)}</td><td class="no-print"><button class="btn danger smallbtn" onclick="deleteMaster('material','${x.id}')">Delete</button></td></tr>`).join('')}</table></div></div>
 <div class="card"><h2>Master Packaging</h2><div class="row3 no-print"><input id="mPKName" placeholder="Nama packaging"><select id="mPKType"><option value="INNER">Inner</option><option value="OUTER">Outer</option></select><input id="mPKUnit" placeholder="Satuan"><input id="mPKMin" type="number" placeholder="Stok minimum"><button class="btn" onclick="addMasterPK()">Tambah Packaging</button></div><div class="tablewrap fit"><table><tr><th>Kode</th><th>Item</th><th>Jenis</th><th>Satuan</th><th class="num">Min</th><th class="no-print">Aksi</th></tr>${db.packaging.map(x=>`<tr><td>${esc(x.id)}</td><td>${esc(x.name)}</td><td>${packTypeLabel(x.type)}</td><td>${esc(x.unit)}</td><td class="num">${fmt(x.minStock)}</td><td class="no-print"><button class="btn danger smallbtn" onclick="deleteMaster('packaging','${x.id}')">Delete</button></td></tr>`).join('')}</table></div></div>
 <div class="card"><div class="cardhead"><h2>Riwayat Perubahan</h2><button class="btn secondary smallbtn no-print" onclick="clearAudit()">Bersihkan Riwayat</button></div><div class="tablewrap fit"><table><thead><tr><th>Waktu</th><th>Data</th><th>Aksi</th><th>Referensi</th><th>Keterangan</th></tr></thead><tbody>${(db.auditTrail||[]).slice(0,100).map(a=>`<tr><td>${new Date(a.at).toLocaleString('id-ID')}</td><td>${esc(a.entity)}</td><td>${esc(a.action)}</td><td>${esc(a.ref||'-')}</td><td>${esc(a.note||'-')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Belum ada perubahan data.</td></tr>'}</tbody></table></div></div>
 <div class="card no-print"><h2>Backup Data</h2><p class="small">Data tersimpan lokal pada browser/perangkat ini. Backup secara berkala.</p><div class="actions"><button class="btn secondary" onclick="backupData()">Download Backup JSON</button><label class="btn secondary" style="text-align:center">Restore Backup<input id="restoreFile" type="file" accept="application/json" style="display:none" onchange="restoreData(event)"></label><button class="btn danger" onclick="resetData()">Reset Semua Data</button></div></div>`
}
window.savePrintWidth=()=>{localStorage.setItem(PRINTKEY,$('#printWidth').value);alert('Setting printer thermal disimpan: '+$('#printWidth').value+' mm.')}
function nextCode(prefix,arr){let max=arr.reduce((m,x)=>Math.max(m,Number(String(x.id).replace(/\D/g,''))||0),0);return prefix+String(max+1).padStart(3,'0')}
window.addMasterProduct=()=>{let name=$('#mProdName').value.trim();if(!name)return alert('Nama produk wajib diisi.');let id=nextCode('FG',db.products),packSize=Math.max(1,Number($('#mProdPack')?.value)||1),reg=Number($('#mProdReg').value),res=Number($('#mProdRes').value);db.products.push({id,name,unit:'pcs',packSize,priceRegular:reg,priceRegularPack:Number($('#mProdRegPack')?.value)||(reg*packSize),priceReseller:res,priceResellerPack:Number($('#mProdResPack')?.value)||(res*packSize),hpp:Number($('#mProdHpp').value),minStock:Number($('#mProdMin').value)});db.fgStock[id]=0;save()}
window.editPackPricing=id=>{let p=db.products.find(x=>x.id===id);if(!p)return;let ps=prompt('Isi per Pack (Pcs):',p.packSize||1);if(ps===null)return;ps=Math.max(1,Number(ps)||1);let rp=prompt('Harga Reguler / Pack:',p.priceRegularPack||p.priceRegular*ps);if(rp===null)return;let sp=prompt('Harga Reseller / Pack:',p.priceResellerPack||p.priceReseller*ps);if(sp===null)return;p.packSize=ps;p.priceRegularPack=Number(rp)||0;p.priceResellerPack=Number(sp)||0;save()}
window.addMasterRM=()=>{let name=$('#mRMName').value.trim();if(!name)return alert('Nama raw material wajib diisi.');db.materials.push({id:nextCode('RM',db.materials),name,unit:$('#mRMUnit').value||'pcs',stock:0,avgCost:0,minStock:Number($('#mRMMin').value)});save()}
window.addMasterPK=()=>{let name=$('#mPKName').value.trim();if(!name)return alert('Nama packaging wajib diisi.');db.packaging.push({id:nextCode('PK',db.packaging),name,type:$('#mPKType').value,unit:$('#mPKUnit').value||'pcs',stock:0,avgCost:0,minStock:Number($('#mPKMin').value)});save()}
window.deleteMaster=(kind,id)=>{let linked=false,name='';if(kind==='product'){let x=db.products.find(v=>v.id===id);name=x?.name||id;linked=db.orders.some(o=>(o.items||[]).some(i=>i.productId===id))||db.productions.some(p=>p.productId===id)||Number(db.fgStock[id]||0)!==0;if(linked)return alert('Item tidak bisa dihapus karena sudah memiliki transaksi/stock.');if(!confirm(`Delete produk ${name}?`))return;db.products=db.products.filter(x=>x.id!==id);delete db.fgStock[id]}else if(kind==='material'){let x=db.materials.find(v=>v.id===id);name=x?.name||id;linked=db.materialTx.some(t=>t.itemId===id)||Number(x?.stock||0)!==0;if(linked)return alert('Item tidak bisa dihapus karena sudah memiliki transaksi/stock.');if(!confirm(`Delete raw material ${name}?`))return;db.materials=db.materials.filter(x=>x.id!==id)}else{let x=db.packaging.find(v=>v.id===id);name=x?.name||id;linked=db.packagingTx.some(t=>t.itemId===id)||Number(x?.stock||0)!==0;if(linked)return alert('Item tidak bisa dihapus karena sudah memiliki transaksi/stock.');if(!confirm(`Delete packaging ${name}?`))return;db.packaging=db.packaging.filter(x=>x.id!==id)}save()}
window.clearAudit=()=>{if(confirm('Bersihkan seluruh riwayat perubahan?')){db.auditTrail=[];save()}}
window.backupData=()=>{let b=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='cemilan-momcip-backup-'+today()+'.json';a.click();URL.revokeObjectURL(a.href)}
window.restoreData=e=>{let f=e.target.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{db=JSON.parse(r.result);save();alert('Backup berhasil direstore.')}catch(err){alert('File backup tidak valid.')}};r.readAsText(f)}
window.resetData=()=>{if(confirm('Hapus semua data aplikasi? Tindakan ini tidak bisa dibatalkan.')){db=cloneSeed();save()}}

buildNav();render('dashboard');setInterval(()=>{let c=$('#clock');if(c)c.textContent=new Date().toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'})},1000);
